<div class="max-w-xl bg-white p-8 rounded-xl border border-zinc-200 shadow-sm space-y-6"><div><h1 class="text-2xl font-bold">STALL INFORMATION</h1><p class="text-sm text-zinc-500">Manage your campus food stall details and operating status</p></div><form wire:submit="updateStall" class="space-y-4"><flux:input label="Stall Name" wire:model="name" required /><flux:input label="Canteen Location" wire:model="location" required /><div><label class="block text-sm font-medium text-zinc-700 mb-1">Operating Status</label><select wire:model="status" class="w-full rounded-lg border-zinc-300 border px-3 py-2 text-sm bg-white"><option value="active">Active</option><option value="inactive">Inactive</option></select></div><flux:button type="submit" variant="primary">Save Changes</flux:button></form></div>